// Generated by scripts/sync-valuation.py from shared/valuation/network.js as rp-valuation-network.js; edit the shared source.
// Trade-network connectivity and single-town loss. Pure ES module.
//
// The graph is undirected. Removing a town that separates two nodes which were
// connected before yields loss Infinity. A leaf's own disappearance is not a
// connectivity loss; an already disconnected graph does not create a false
// positive; an alternative path keeps the graph connected. No military or
// strategic-location score is accepted or invented.

import {isFiniteNumber} from './rp-valuation-weights.js';

function key(id) {
  return String(id);
}

function validGraph(nodes, edges) {
  if (!Array.isArray(nodes)) return {status: 'invalid', reason: 'nodes-array-required'};
  if (!Array.isArray(edges)) return {status: 'invalid', reason: 'edges-array-required'};
  const set = new Set(nodes.map(key));
  if (set.size !== nodes.length) return {status: 'invalid', reason: 'duplicate-node-id'};
  for (const edge of edges) {
    if (!edge || edge.a === undefined || edge.b === undefined) return {status: 'invalid', reason: 'edge-endpoints-required'};
    if (!set.has(key(edge.a)) || !set.has(key(edge.b))) return {status: 'invalid', reason: `unknown-edge-endpoint:${edge.a}-${edge.b}`};
    if (key(edge.a) === key(edge.b)) return {status: 'invalid', reason: 'self-edge'};
  }
  return {status: 'estimated', set};
}

function componentMap(nodes, edges, exclude = new Set()) {
  const adjacency = new Map();
  for (const node of nodes) {
    if (exclude.has(key(node))) continue;
    adjacency.set(key(node), new Set());
  }
  for (const edge of edges) {
    const a = key(edge.a);
    const b = key(edge.b);
    if (!adjacency.has(a) || !adjacency.has(b)) continue;
    adjacency.get(a).add(b);
    adjacency.get(b).add(a);
  }
  const components = {};
  let component = 0;
  for (const start of adjacency.keys()) {
    if (components[start] !== undefined) continue;
    const stack = [start];
    components[start] = component;
    while (stack.length) {
      const current = stack.pop();
      for (const next of adjacency.get(current)) {
        if (components[next] !== undefined) continue;
        components[next] = component;
        stack.push(next);
      }
    }
    component++;
  }
  return {components, componentCount: component};
}

export function networkComponents({nodes, edges, exclude = []} = {}) {
  const graph = validGraph(nodes, edges);
  if (graph.status === 'invalid') return Object.freeze({status: 'invalid', reason: graph.reason, components: null});
  const excluded = new Set(exclude.map(key));
  const result = componentMap(nodes, edges, excluded);
  return Object.freeze({
    status: 'estimated',
    components: Object.freeze(result.components),
    componentCount: result.componentCount,
    excluded: Object.freeze([...excluded])
  });
}

export function analyzeRemoval({nodes, edges, removeNode} = {}) {
  const graph = validGraph(nodes, edges);
  if (graph.status === 'invalid') return Object.freeze({status: 'invalid', reason: graph.reason, severed: null});
  if (removeNode === undefined) return Object.freeze({status: 'invalid', reason: 'removeNode-required', severed: null});
  const removeKey = key(removeNode);
  if (!graph.set.has(removeKey)) return Object.freeze({status: 'invalid', reason: 'removeNode-not-in-graph', severed: null});
  const remaining = nodes.filter(node => key(node) !== removeKey);
  const before = componentMap(nodes, edges);
  const after = componentMap(nodes, edges, new Set([removeKey]));
  const groups = new Map();
  for (const node of remaining) {
    const nodeKey = key(node);
    const beforeComponent = before.components[nodeKey];
    const afterComponent = after.components[nodeKey];
    if (!groups.has(beforeComponent)) groups.set(beforeComponent, new Map());
    const afterGroups = groups.get(beforeComponent);
    afterGroups.set(afterComponent, (afterGroups.get(afterComponent) || 0) + 1);
  }
  let disconnectedPairs = 0;
  const splitGroups = [];
  for (const [beforeComponent, afterGroups] of groups) {
    const total = [...afterGroups.values()].reduce((sum, count) => sum + count, 0);
    if (afterGroups.size <= 1) continue;
    const connectedPairs = total * (total - 1) / 2;
    let stillConnectedPairs = 0;
    for (const count of afterGroups.values()) stillConnectedPairs += count * (count - 1) / 2;
    const splitPairs = connectedPairs - stillConnectedPairs;
    if (splitPairs > 0) {
      disconnectedPairs += splitPairs;
      splitGroups.push({
        beforeComponent,
        afterComponents: Object.freeze([...afterGroups.keys()]),
        disconnectedPairs: splitPairs
      });
    }
  }
  return Object.freeze({
    status: 'estimated',
    removeNode,
    severed: disconnectedPairs > 0,
    disconnectedPairs,
    splitGroups: Object.freeze(splitGroups),
    before: Object.freeze({components: Object.freeze(before.components), componentCount: before.componentCount}),
    after: Object.freeze({components: Object.freeze(after.components), componentCount: after.componentCount}),
    evidence: Object.freeze({
      note: 'only pairs connected before removal and separated after removals count; leaves contribute zero pairs'
    })
  });
}

// Actual resource-card loss at the removed town. Reassigning the card to
// another settlement does NOT keep the source town's contribution: the source
// city is gone, so the card is lost by default. Only an explicit replacement
// compensation or an explicit confirmation that the source is retained can
// reduce the loss. A card amount already embedded in the node's own net output
// is subtracted so the same yield is not counted twice.
export function resourceCardLoss({cards, removedNodeId} = {}) {
  if (!Array.isArray(cards)) return Object.freeze({status: 'invalid', reason: 'cards-array-required', loss: null});
  if (removedNodeId === undefined) return Object.freeze({status: 'invalid', reason: 'removedNodeId-required', loss: null});
  const removedKey = key(removedNodeId);
  const contributions = [];
  const missing = [];
  let loss = 0;
  for (const card of cards) {
    if (!card || card.sourceId === undefined) {
      missing.push({card, field: 'sourceId'});
      continue;
    }
    if (key(card.sourceId) !== removedKey) continue;
    if (!isFiniteNumber(card.marginalValue) || card.marginalValue < 0) {
      missing.push({card: card.key ?? null, field: 'marginalValue'});
      continue;
    }
    let included = 0;
    if (card.alreadyIncludedInNodeOutput === true) included = card.marginalValue;
    else if (isFiniteNumber(card.alreadyIncludedInNodeOutput) && card.alreadyIncludedInNodeOutput >= 0) included = card.alreadyIncludedInNodeOutput;
    else if (card.alreadyIncludedInNodeOutput !== undefined && card.alreadyIncludedInNodeOutput !== false) {
      missing.push({card: card.key ?? null, field: 'alreadyIncludedInNodeOutput'});
      continue;
    }
    if (card.retainedSourceConfirmed !== undefined && typeof card.retainedSourceConfirmed !== 'boolean') {
      missing.push({card: card.key ?? null, field: 'retainedSourceConfirmed'});
      continue;
    }
    let compensation = 0;
    if (card.compensationValue !== undefined) {
      if (!isFiniteNumber(card.compensationValue) || card.compensationValue < 0) {
        missing.push({card: card.key ?? null, field: 'compensationValue'});
        continue;
      }
      compensation = card.compensationValue;
    }
    const actualLoss = card.retainedSourceConfirmed === true
      ? 0
      : Math.max(0, card.marginalValue - included - compensation);
    loss += actualLoss;
    contributions.push(Object.freeze({
      key: card.key ?? null,
      sourceId: card.sourceId,
      marginalValue: card.marginalValue,
      alreadyIncludedInNodeOutput: included,
      compensationValue: compensation,
      reassignedTo: card.reassignedTo ?? null,
      retainedSourceConfirmed: card.retainedSourceConfirmed === true,
      actualLoss,
      reason: card.retainedSourceConfirmed === true
        ? 'source-retention-explicitly-confirmed'
        : compensation > 0
          ? 'replacement-compensation-subtracted'
          : included > 0
            ? 'already-included-and-source-lost'
            : 'source-lost-even-if-reassigned'
    }));
  }
  if (missing.length) return Object.freeze({status: 'not-estimated', reason: 'resource-card-context-missing', loss: null, missing: Object.freeze(missing), contributions: Object.freeze(contributions)});
  if (!isFiniteNumber(loss)) return Object.freeze({status: 'invalid', reason: 'resource-loss-overflow', loss: null});
  return Object.freeze({status: 'estimated', loss, contributions: Object.freeze(contributions), evidence: Object.freeze({removedNodeId, cardCount: contributions.length})});
}

// Single removed-town loss:
//   own remaining net output
// + actual lost resource cards
// - settlement-point-count relief supplied by the caller
// Connectivity severance overrides the total with Infinity. No abandon action
// is executed; this is an evaluation only.
export function evaluateTownLoss({
  nodes,
  edges,
  removeNode,
  nodeValues = {},
  resourceCards = [],
  settlementCountRelief = 0
} = {}) {
  const removal = analyzeRemoval({nodes, edges, removeNode});
  if (removal.status === 'invalid') return Object.freeze({status: 'invalid', reason: removal.reason, total: null, removal});
  const entry = nodeValues[removeNode] ?? nodeValues[key(removeNode)];
  let own = null;
  if (isFiniteNumber(entry)) own = entry;
  else if (entry && isFiniteNumber(entry.remainingNetOutput)) own = entry.remainingNetOutput;
  else if (entry && isFiniteNumber(entry.netOutput)) own = entry.netOutput;
  if (!isFiniteNumber(settlementCountRelief) || settlementCountRelief < 0) {
    return Object.freeze({status: 'invalid', reason: 'settlementCountRelief-non-negative-finite', total: null, removal});
  }
  const resources = resourceCardLoss({cards: resourceCards, removedNodeId: removeNode});
  if (resources.status === 'invalid') return Object.freeze({status: 'invalid', reason: resources.reason, total: null, removal, resources});
  if (removal.severed) {
    const missing = [];
    if (own === null) missing.push(`nodeValue:${removeNode}`);
    if (resources.status !== 'estimated') missing.push(...(resources.missing || []).map(item => item.field ?? 'resource-card'));
    return Object.freeze({
      status: 'severed',
      total: Infinity,
      finite: false,
      connectivityLoss: Infinity,
      ownRemainingNetOutput: own,
      resourceLoss: resources.loss,
      settlementCountRelief,
      removal,
      resources,
      missing: Object.freeze(missing),
      evidence: Object.freeze({note: 'removal separates previously connected nodes; Infinity is intentional'})
    });
  }
  if (resources.status !== 'estimated') {
    return Object.freeze({
      status: 'not-estimated',
      reason: 'resource-card-context-missing',
      total: null,
      removal,
      resources,
      missing: resources.missing
    });
  }
  if (own === null) {
    return Object.freeze({
      status: 'not-estimated',
      reason: 'own-remaining-net-output-required',
      total: null,
      removal,
      resources,
      missing: Object.freeze([`nodeValue:${removeNode}`])
    });
  }
  return Object.freeze({
    status: 'estimated',
    total: own + resources.loss - settlementCountRelief,
    finite: true,
    ownRemainingNetOutput: own,
    resourceLoss: resources.loss,
    settlementCountRelief,
    removal,
    resources,
    evidence: Object.freeze({
      formula: 'ownRemainingNetOutput + resourceLoss - settlementCountRelief',
      noMilitaryScore: true
    })
  });
}
